SELECT
FROM users u LEFT JOIN user_agent_level ual ON ual.user_id = u.id LEFT JOIN agent_levels al ON al.id = ual.level_id WHERE u.role = 'agent'
AND ( u.username LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') )
AND u.status = #{status}
AND al.name = #{levelName}
AND u.parent_id = #{parentAgentId}
AND DATE(u.created_at) >= DATE(#{createTimeStart})
AND DATE(u.created_at) <= DATE(#{createTimeEnd})
ORDER BY
u.created_at u.updated_at u.username u.status al.name u.created_at
ASC DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM users u LEFT JOIN user_agent_level ual ON ual.user_id = u.id LEFT JOIN agent_levels al ON al.id = ual.level_id WHERE u.role = 'agent'
AND ( u.username LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') )
AND u.status = #{status}
AND al.name = #{levelName}
AND u.parent_id = #{parentAgentId}
AND DATE(u.created_at) >= DATE(#{createTimeStart})
AND DATE(u.created_at) <= DATE(#{createTimeEnd})
